const documents = [
  'This budget-friendly notebook computer is perfect for students.',
  'Premium gaming desktop with top-tier graphics card included.',
  'Affordable smartphone with surprisingly good camera quality.'
];

// Pre-compute and store each document's embedding (lesson 3's vector
// database will handle this at genuine scale; this demonstrates the
// underlying concept directly first)
const documentEmbeddings = await Promise.all(
  documents.map((doc) => embeddingClient.embed(doc))
);

async function semanticSearch(query: string, topN: number = 1) {
  const queryEmbedding = await embeddingClient.embed(query);

  const scored = documents.map((doc, i) => ({
    document: doc,
    similarity: cosineSimilarity(queryEmbedding, documentEmbeddings[i])
  }));

  return scored.sort((a, b) => b.similarity - a.similarity).slice(0, topN);
}

const results = await semanticSearch('affordable laptop');
// RESULT: document 1 ('budget-friendly notebook computer') scores
// HIGHEST, despite sharing ZERO exact words with the query
// ('affordable laptop' vs 'budget-friendly notebook computer') -
// Module 19's keyword search would have returned NOTHING relevant
// at all, since no shared keywords exist between query and document

