STEP 1 - RETRIEVE genuinely relevant documents using lessons 2-3's
exact semantic search infrastructure:

async function answerQuestion(userQuestion: string) {
  const queryEmbedding = await embeddingClient.embed(userQuestion);
  const retrievedDocs = await vectorDb.query({
    vector: queryEmbedding,
    topK: 3 // the 3 most genuinely relevant documents
  });

  // STEP 2 - AUGMENT the prompt with the actual, retrieved content,
  // explicitly instructing the model to use ONLY this material
  const context = retrievedDocs.map((doc) => doc.metadata.content).join('\n\n');
  const prompt = `Answer the question using ONLY the information in the context below. If the answer is not genuinely present in the context, say "I don't have enough information to answer this."

Context:
${context}

Question: ${userQuestion}`;

  // STEP 3 - GENERATE the final answer, now genuinely grounded in
  // the retrieved, verifiable context rather than ungrounded memory
  const answer = await llmClient.generate({ prompt });

  return { answer, sources: retrievedDocs.map((doc) => doc.metadata.title) };
}

