sections.content:
Defining a SPECIFIC, deliberately limited set of tools the agent can
choose to call, directly extending Module 30's least-privilege
discipline to tool definition itself:

const tools = [
  {
    name: 'search_orders',
    description: 'Search this user\'s own order history by date range',
    parameters: { startDate: 'string', endDate: 'string' }
    // deliberately scoped to THIS user's own orders only - never a
    // genuinely unbounded 'search all orders in the entire database'
  },
  {
    name: 'request_refund',
    description: 'Submit a refund request for a specific order, requiring human approval',
    parameters: { orderId: 'string', reason: 'string' }
    // deliberately REQUESTS rather than directly EXECUTES a refund -
    // a genuinely consequential, financial action requires human
    // approval, never fully autonomous agent execution
  }
];

// The agent loop: the LLM decides WHICH tool (if any) to call,
// based on the user's own request
async function runAgent(userMessage: string) {
  const decision = await llmClient.generateWithTools({ message: userMessage, tools });

  if (decision.toolCall) {
    // Execute ONLY the specific, named tool the model chose, with
    // ITS OWN, separately-enforced authorization/validation
    return await executeTool(decision.toolCall.name, decision.toolCall.arguments);
  }
  return decision.textResponse;
}

