interface ToolCall {
  name: string;
  arguments: Record<string, unknown>;
}

// TODO: build executeTool(toolCall, currentUserId) for a
// 'cancel_subscription' tool - it should NEVER trust any userId or
// subscriptionId from toolCall.arguments, always operating on
// currentUserId's own subscription, and should create a pending
// approval request rather than directly canceling

codingChallenge.solutionExample:
interface ToolCall {
  name: string;
  arguments: Record<string, unknown>;
}

async function executeTool(toolCall: ToolCall, currentUserId: string) {
  if (toolCall.name === 'cancel_subscription') {
    // NEVER use any userId or subscriptionId from toolCall.arguments
    // - always look up the CURRENT, authenticated user's own,
    // actual subscription independently
    const subscription = await subscriptionsRepository.findByUserId(currentUserId);

    if (!subscription) {
      return { success: false, error: 'No active subscription found for this user' };
    }

    // This is a genuinely consequential, hard-to-reverse action -
    // create a PENDING approval request rather than directly
    // executing the cancellation
    await approvalRequestsRepository.create({
      type: 'cancel_subscription',
      userId: currentUserId,
      subscriptionId: subscription._id,
      status: 'pending_human_approval',
      requestedAt: new Date()
    });

    return { success: true, message: 'Cancellation request submitted for approval' };
  }
}

