const evalCases = [
  {
    question: 'What is your return policy?',
    expectedToBeAnswerable: true,
    mustMention: ['30 days', 'receipt'] // genuine facts that must
      // genuinely appear, not an exact, full-string match
  },
  {
    question: 'What are your holiday closure dates this year?',
    expectedToBeAnswerable: false // this company's documents
      // genuinely don't contain this - the CORRECT answer is
      // honestly declining, exactly lesson 4's codeLesson's trace
  }
];

async function runEvaluation() {
  const results = [];

  for (const evalCase of evalCases) {
    const { answer, sources } = await answerQuestion(evalCase.question);

    const declinedToAnswer = answer.includes("don't have enough information");

    if (evalCase.expectedToBeAnswerable) {
      const mentionsRequiredFacts = evalCase.mustMention.every((fact) => answer.includes(fact));
      results.push({
        question: evalCase.question,
        passed: !declinedToAnswer && mentionsRequiredFacts,
        sources
      });
    } else {
      // the CORRECT behavior here is genuinely declining to answer -
      // a confident, fabricated answer would be a FAILED evaluation
      results.push({
        question: evalCase.question,
        passed: declinedToAnswer,
        sources
      });
    }
  }

  const passRate = results.filter((r) => r.passed).length / results.length;
  console.log(`Evaluation pass rate: ${(passRate * 100).toFixed(1)}%`);
  return results;
}

